docker exec gp-postgres-crm psql -U postgres -d testdb -tAc "select to_char(\"enviarEm\" - interval '3 hours','DD/MM (Dy)'), count(*), to_char(min(\"enviarEm\") - interval '3 hours','HH24:MI'), to_char(max(\"enviarEm\") - interval '3 hours','HH24:MI') from \"Agendamento\" where observacoes like 'robo-recuperacao 22/10%' group by 1, date_trunc('day',\"enviarEm\" - interval '3 hours') order by date_trunc('day',\"enviarEm\" - interval '3 hours') limit 6;"
docker exec gp-postgres-crm psql -U postgres -d testdb -tAc "select count(*), count(distinct numero), bool_and(\"cancelarSeResponder\") from \"Agendamento\" where observacoes like 'robo-recuperacao 22/10%';"
